/// <summary>
/// PaffH 05.03.25
/// </summary>
/// <param name = "_contract">NDXUmsatzClassParmContract</param>
/// <returns>System.Threading.Tasks.Task</returns>
static server Task getUmsAllianceFromNDXUmsatzClassParmContractAsync(NDXUmsatzClassParmContract _contract)
{
    return runAsync(classnum(NDXUmsatzClass), staticmethodstr(NDXUmsatzClass, getUmsAlliance), _contract.containerFromContract());
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "nDXUmsatzClass">NDXUmsatzClass</param>
/// <returns>thread</returns>
static server System.Threading.Tasks.Task runGetUmsAlliance(NDXUmsatzClass nDXUmsatzClass)
{
    System.Threading.Tasks.Task      t;
    str         waringMsg;
    boolean     lThread;
    ;
    lThread = nDXUmsatzClass.parmLThread();
    if (lThread)
    {
        t = NDXUmsatzClassThread::getUmsAlliance(t, nDXUmsatzClass);
        if (t.Status == System.Threading.Tasks.TaskStatus::Faulted || t.Status == System.Threading.Tasks.TaskStatus::Canceled)
        {
            waringMsg = strfmt('%1 [%2]',
                           nDXUmsatzClass.parmlAlliance() ? "@NDX:NDXAssociationStructure" : "@NDX:NDXSalesDistrict1",
                           nDXUmsatzClass.parmlAlliance() ? nDXUmsatzClass.parmAccountNum() : nDXUmsatzClass.parmSalesGroupId());
            Warning(strfmt("@NDX:NDXThreadErrorAt", waringMsg));
        }
    }
    else
    {
        NDXUmsatzClassThread::getUmsAlliance(t, nDXUmsatzClass);
    }
    return t;
}

/// <summary>
/// DebuC 22.09.23
/// last modified: PaffH 16.01.25
/// </summary>
/// <param name = "t">Thread</param>
