/// <returns>Thread</returns>
public server static System.Threading.Tasks.Task getUmsAlliance(System.Threading.Tasks.Task t, NDXUmsatzClass nDXUmsatzClass)
{
    container   parm = connull();
    boolean     lThread;
    System.Threading.Tasks.Task lTask = t;
    NDXUmsatzClassParmContract nDXUmsatzClassParmContract = NDXUmsatzClassParmContract::contractFromNDXUmsatzClass(nDXUmsatzClass);
    parm = nDXUmsatzClassParmContract.containerFromContract();

    //parm += nDXUmsatzClass.parmUmsSignature();
    //parm += nDXUmsatzClass.parmLThread();
    //parm += nDXUmsatzClass.parmlAlliance();
    //parm += nDXUmsatzClass.parmAccountNum();
    //parm += nDXUmsatzClass.parmSalesGroupId();
    //parm += nDXUmsatzClass.parmDataVersion();
    //parm += nDXUmsatzClass.parmlBasisUmsLfdJ();
    //parm += nDXUmsatzClass.parmLCSIncl();
    //parm += nDXUmsatzClass.parmNDXVerband().parmlSalesGroupMaster();
    //parm += conlen(nDXUmsatzClass.parmConFirmen());
    //parm += nDXUmsatzClass.parmConFirmen();

    lThread = nDXUmsatzClass.parmLThread();
    if (lThread)
    {
        //t.setInputParm(parm);
        //t.run(classnum(NDXUmsatzClassThread), staticmethodstr(NDXUmsatzClassThread, getUmsAllianceHandler));
        lTask = runAsync(classnum(NDXUmsatzClassThread), staticmethodstr(NDXUmsatzClassThread, getUmsAllianceHandler),parm);            
    }
    else
    {
        NDXUmsatzClass::getUmsAlliance(parm);
    }

    return lTask;
}

