/// <param name = "inputParm">Container</param>
static server void getValuesCust(Container inputParm)
{

    NDXTmpKumUmsCust                    tmpKumUmsCust;
    NDXTmpKumUmsCust                    tmpKumUmsCustAll;
    NDXTmpCustomerAlliance              nDXTmpCustomerAlliance;
    //    NDX_TmpCustomerAllianceFirma        nDX_TmpCustomerAllianceFirma;
    NDXKumUmsCust                       kumUmsCust;
    NDXKumBonCust                       kumBonCust;
    NDX_CentralStoreDistributionTable   nDXCentralStoreDistributionTable;
    //    NDX_CentralStoreDistributionLine    nDX_CentralStoreDistributionLine;
    NDXTmpUmsatzClassThreadControl      nDXTmpUmsatzClassThreadControl;
    NDXThreadControl                    nDXThreadControl;
    CustTable                           custTablePartyId;
    CustTable                           custTableChild;
    //NDX_RLSCompany                      nDX_RLSCompany;

    AccountNum                  accountNum;
    accountNum                  accountNumSearch;
    //NDXUmsSignature             umsSignature;
    //NDXMonthYearSignature       monthYearSignature;
    //int                         conLen;
    //int                         nAnzChilds;
    int                         i;
    int                         nAnz;
    NDXCompanyBE                lfirma;
    //NDXCompanyBE                firma;
    container                   conFirmen = connull();
    container                   conCompanies;
    //NDXYear                     yearlfdJ, yearVJ;
    //boolean                     lCSIncl;
