    //boolean                     lUseCalculatedData;
    //boolean                     lGetDataOnly;
    //boolean                     lGetDataPerChild;
    //boolean                     lThread;
    //boolean                     lAlliance;
    //boolean                     lSalesGroupMaster;
    //CommissSalesGroup           salesGroup;
    str                         text;
    CompanyId                   company;
    container                   conCompanys = connull();
    boolean                     lAllianceValues;
    AccountNum                  l_Alliance;
    int                         anzDebitor;
    //NDXSalesPerDebitor          lSalesPerDebitor;
    RefRecId                    partyIdAlliance;

    Query                       q;
    QueryRun                    qr;
    QueryBuildDataSource        qbds;
    Map                         accountNumPerCompany;
    System.Exception ex;
    str tmpKumUmsCustAllStatus = '';
    str tmpKumUmsCustStatus = '';
    str errorStr = '';
    boolean lgetDataForAllCompanies = false;


    //const str                   constUmsSignature         = 'UmsSignature';
    //const str                   constAccountNum           = 'AccountNum';
    //const str                   constNAnzChilds           = 'NAnzChilds';
    //const str                   constConLenFirmen         = 'ConLenFirmen';
    //const str                   constConFirmen            = 'ConFirmen';
    //const str                   constYearlfdJ             = 'YearlfdJ';
    //const str                   constMonthYearSignature   = 'MonthYearSignature';
    //const str                   constYearVJ               = 'YearVJ';
    //const str                   constLCSIncl              = 'LCSIncl';
    //const str                   constLwithProt            = 'LwithProt';
    //const str                   constlUseCalculatedData   = 'lUseCalculatedData';
    //const str                   constLGetDataOnly         = 'LGetDataOnly';
    //const str                   constlGetDataPerChild     = 'lGetDataPerChild';
    //const str                   constLThread              = 'LThread';
    //const str                   constlAlliance            = 'lAlliance';
    //const str                   constSalesGroupId         = 'SalesGroupId';
    //const str                   constlSalesGroupMaster    = 'lSalesGroupMaster';
    //const str                   constlSalesPerDebitor     = 'lSalesPerDebitor';
    //const str                   constFirma                = 'Firma';
    //const str                   constProcessSignature     = 'ProcessSignature';
    //container                   conParm;
    //int                         ci;
    //NDXSignature                processSignature;

    //for(ci = 1; ci<= conLen(inputParm);ci++)
    //{
    //    conParm = conPeek(inputParm, ci);

    //    switch(conPeek(conParm, 1))
    //    {
    //        case constUmsSignature:
    //            umsSignature = conPeek(conParm, 2);
    //            break;
    //        case constAccountNum:
    //            accountNum = conPeek(conParm, 2);
    //            break;
    //        case constNAnzChilds:
    //            nAnzChilds = conPeek(conParm, 2);
    //            break;
    //        case constConLenFirmen:
    //            conLen = conPeek(conParm, 2);
    //            break;
    //        case constConFirmen:
    //            conFirmen = conPeek(conParm, 2);
    //            break;
    //        case constYearlfdJ:
    //            yearlfdJ = conPeek(conParm, 2);
    //            break;
    //        case constMonthYearSignature:
    //            monthYearSignature = conPeek(conParm, 2);
    //            break;
    //        case constYearVJ:
    //            yearVJ = conPeek(conParm, 2);
    //            break;
    //        case constLCSIncl:
    //            lCSIncl = conPeek(conParm, 2);
    //            break;
    //        case constLwithProt:
    //            lWithProt = conPeek(conParm, 2);
    //            break;
    //        case constlUseCalculatedData:
    //            lUseCalculatedData = conPeek(conParm, 2);
    //            break;
    //        case constLGetDataOnly:
    //            lGetDataOnly = conPeek(conParm, 2);
    //            break;
    //        case constlGetDataPerChild:
    //            lGetDataPerChild = conPeek(conParm, 2);
    //            break;
    //        case constLThread:
    //            lThread = conPeek(conParm, 2);
    //            break;
    //        case constlAlliance:
    //            lAlliance = conPeek(conParm, 2);
    //            break;
    //        case constSalesGroupId:
    //            salesGroup = conPeek(conParm, 2);
    //            break;
    //        case constlSalesGroupMaster:
    //            lSalesGroupMaster = conPeek(conParm, 2);
    //            break;
    //        case constlSalesPerDebitor:
    //            lSalesPerDebitor = conPeek(conParm, 2);
    //            break;
    //        case constFirma:
    //            firma = conPeek(conParm, 2);
    //            break;
    //        case constProcessSignature:
    //            processSignature = conPeek(conParm, 2);
    //            break;
    //    }
    //}

    NDXUmsatzClassParmContract nDXUmsatzClassParmContract = NDXUmsatzClassParmContract::contractFromCon2Dim(inputParm);
    accountNum = nDXUmsatzClassParmContract.parmAccountNum();
    conFirmen = nDXUmsatzClassParmContract.parmConFirmen();

    // Parameter übernehmen
    for (i = 1; i <= nDXUmsatzClassParmContract.parmAnzFirmen(); i++)
    {
        lfirma           = conpeek(conFirmen, i);
        conCompanys      += NDXHelperCommon::NDXCompanys2CompanyId(lfirma);
    }

    if (nDXUmsatzClassParmContract.parmLSalesPerDebitor())
    {
        accountNum  =  NDXVerbandSE::construct().parmMasterAllianceAllDebitor();
    }

    if (nDXUmsatzClassParmContract.parmLThread())
    {
        nDXThreadControl.Signature      = nDXUmsatzClassParmContract.parmProcessSignature();
        nDXThreadControl.ThreadSession = SessionId();
        nDXThreadControl.MethodName     = staticmethodstr(NDXUmsatzClassThread, getValuesCust);
        nDXThreadControl.ClassName      = classstr(NDXUmsatzClassThread);
        nDXThreadControl = NDXThreadControl::findOrCreate(nDXThreadControl);

        nDXTmpUmsatzClassThreadControl = NDXTmpUmsatzClassThreadControl::find(nDXUmsatzClassParmContract.parmUmsSignature(), NDXThreadTypes::getValuesCust, true);
    }

    lAllianceValues = NDXUmsatzClass::AllianceOrSalesGroupValues(
        nDXUmsatzClassParmContract.parmLAlliance(),
        nDXUmsatzClassParmContract.parmLUseCalculatedData(),
        nDXUmsatzClassParmContract.parmLGetDataOnly(),
        nDXUmsatzClassParmContract.parmLSalesGroupMaster());

    if (lAllianceValues)
    {
        custTablePartyId = NDXUmsatzClass::getCustTableFromAccount(accountNum, nDXUmsatzClassParmContract.parmFirma());
    }

    q = new Query();
    qbds = q.addDataSource(tablenum(NDXTmpKumUmsCust));
    qbds.addRange(fieldnum(NDXTmpKumUmsCust, UmsSignature)).value(nDXUmsatzClassParmContract.parmUmsSignature());
    qbds.addRange(fieldnum(NDXTmpKumUmsCust, MonthYearSignature)).value(nDXUmsatzClassParmContract.parmMonthYearSignature());
    qbds.addRange(fieldnum(NDXTmpKumUmsCust, Company)).value(QueryValue(nDXUmsatzClassParmContract.parmFirma()));
    if (false)
    {
        throw error('Testfehlermeldung [NDXUmsatzClassThread::getValuesCust()] ');
    }

    if (nDXUmsatzClassParmContract.parmLGetDataPerChild())
    {
        // Umsatz je Kunde
        // Daten löschen, die nicht der aktuellen Signatur entsprechen
        if (nDXUmsatzClassParmContract.parmLGetDataOnly())   // Daten neu aufbauen
        {
            for (i=1; i <= conlen(conFirmen)+1; i++)
            {
                if (i <= conlen(conFirmen))
                {
                    lfirma = conpeek(conFirmen, i);
                }
                else
                {
                    if (!lgetDataForAllCompanies)
                    {
                        continue;
                    }
                    lfirma = NDXCompanyBE::AllCompanies;
                }

                if (nDXUmsatzClassParmContract.parmLAlliance())
                {
                    delete_from TmpKumUmsCust
                    where   TmpKumUmsCust.UmsSignature          == nDXUmsatzClassParmContract.parmUmsSignature()         &&
                            TmpKumUmsCust.MonthYearSignature    == nDXUmsatzClassParmContract.parmMonthYearSignature()   &&
                            TmpKumUmsCust.Alliance              == accountNum           &&
                            tmpKumUmsCust.Company               == lfirma;
                }
                else
                {
                    delete_from TmpKumUmsCust
                    where   TmpKumUmsCust.UmsSignature          == nDXUmsatzClassParmContract.parmUmsSignature()         &&
                            TmpKumUmsCust.MonthYearSignature    == nDXUmsatzClassParmContract.parmMonthYearSignature()   &&
                            TmpKumUmsCust.SalesGroup            == nDXUmsatzClassParmContract.parmSalesGroupId()           &&
                            tmpKumUmsCust.Company               == lfirma;
                }
            }
        }
        // Monatsumsatz
        if (lAllianceValues)
        {
            qbds.addRange(fieldnum(NDXTmpKumUmsCust, Alliance)).value(accountNum);
        }
        else
        {
            qbds.addRange(fieldnum(NDXTmpKumUmsCust, SalesGroup)).value(nDXUmsatzClassParmContract.parmSalesGroupId());
        }
    }
    else
    {
        // Umsatz je Kunde
        // Daten löschen, die nicht der aktuellen Signatur entsprechen
        if (nDXUmsatzClassParmContract.parmLGetDataOnly())   // Daten neu aufbauen
        {
            for (i=1; i <= conlen(conFirmen); i++)
            {
                if (i <= conlen(conFirmen))
                {
                    lfirma = conpeek(conFirmen, i);
                }
                else
                {
                    if (!lgetDataForAllCompanies)
                    {
                        continue;
                    }
                    lfirma = NDXCompanyBE::AllCompanies;
                }

                /*ttsbegin;
                while select forupdate tmpKumUmsCust
                    where tmpKumUmsCust.UmsSignature == nDXUmsatzClassParmContract.parmUmsSignature()
                    && tmpKumUmsCust.MonthYearSignature == nDXUmsatzClassParmContract.parmMonthYearSignature()
                    && tmpKumUmsCust.Child == accountNum           
                    && tmpKumUmsCust.Company == lfirma
                {
                    tmpKumUmsCust.delete();
                }
                ttscommit; */

                delete_from tmpKumUmsCust
                    where tmpKumUmsCust.UmsSignature == nDXUmsatzClassParmContract.parmUmsSignature()
                    && tmpKumUmsCust.MonthYearSignature == nDXUmsatzClassParmContract.parmMonthYearSignature()
                    && tmpKumUmsCust.Child == accountNum
                    && tmpKumUmsCust.Company == lfirma;

                if (lfirma != nDXUmsatzClassParmContract.parmFirma())
                {
                    qbds.addRange(fieldnum(NDXTmpKumUmsCust, Company)).value(QueryValue(lfirma));
                }
            }
        }

        // Monatsumsatz
        if (lAllianceValues)
        {
            if (custTablePartyId)
            {
                qbds.addRange(fieldnum(NDXTmpKumUmsCust, Party)).value(queryValue(custTablePartyId.Party));
            }
            else
            {
                qbds.addRange(fieldnum(NDXTmpKumUmsCust, Child)).value(queryValue(accountNum));
            }
        }
        else
        {
            qbds.addRange(fieldnum(NDXTmpKumUmsCust, Child)).value(nDXUmsatzClassParmContract.parmSalesGroupId());
        }
    }
    qr = new QueryRun(q);
    qr.next();
    tmpKumUmsCust = qr.get(tablenum(NDXTmpKumUmsCust));
    if (!tmpKumUmsCust) // Monatsumsatz wurde nocht nicht ermittelt
    {
        text = strfmt("@NDX:NDXDetermineMonthlySalesVolumeOfCustomer",
                    NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())),
                    nDXUmsatzClassParmContract.parmLAlliance() ? NDXUmsatzConstants::Verbandstruktur : NDXUmsatzConstants::Verkaufsbereich,
                    nDXUmsatzClassParmContract.parmLAlliance() ? accountNum       : nDXUmsatzClassParmContract.parmSalesGroupId(),
                    NDXUmsatzConstants::Start, NDXUmsatzConstants::leer);  //[%1] %4: %5Monatsumsätze der Kunden für %3 [%2] ermitteln

        if (nDXUmsatzClassParmContract.parmLThread())
        {
            NDXTmpUmsatzClassThreadControl::setInfoStatic(nDXTmpUmsatzClassThreadControl, text, true);
        }
        if (nDXUmsatzClassParmContract.parmLwithProt())
        {
            NDXUmsatzProt::add(nDXUmsatzClassParmContract.parmUmsSignature(), text, NDXProtStart::Start);
        }
        try
        {
            ttsbegin;
            if (lgetDataForAllCompanies)
            {
                if (lAllianceValues)
                {
                    TmpKumUmsCustAll = NDXTmpKumUmsCust::find(
                nDXUmsatzClassParmContract.parmUmsSignature(),
                nDXUmsatzClassParmContract.parmMonthYearSignature(),
                accountNum, NDXCompanyBE::AllCompanies, accountNum, custTablePartyId.Party, true, true);

                    tmpKumUmsCustAllStatus = strFmt('Seek Signature [%1] MonthYear [%2] Account [%3] Company [%4] found [%5]',
                    nDXUmsatzClassParmContract.parmUmsSignature(),
                    nDXUmsatzClassParmContract.parmMonthYearSignature(),
                    accountNum, NDXCompanyBE::AllCompanies, TmpKumUmsCustAll.RecId > 0);

                }
                else
                {
                    TmpKumUmsCustAll = NDXTmpKumUmsCust::findSalesGroup(
                nDXUmsatzClassParmContract.parmUmsSignature(),
                nDXUmsatzClassParmContract.parmMonthYearSignature(),
                nDXUmsatzClassParmContract.parmSalesGroupId(),
                NDXCompanyBE::AllCompanies, nDXUmsatzClassParmContract.parmSalesGroupId(), true, true);

                    tmpKumUmsCustAllStatus = strFmt('Seek Signature [%1] MonthYear [%2] Account [%3] Company [%4] found [%5]',
                    nDXUmsatzClassParmContract.parmUmsSignature(),
                    nDXUmsatzClassParmContract.parmMonthYearSignature(),
                    nDXUmsatzClassParmContract.parmSalesGroupId(),
                    NDXCompanyBE::AllCompanies, TmpKumUmsCustAll.RecId > 0);
                }
                if (TmpKumUmsCustAll == null)
                {
                    TmpKumUmsCustAll.UmsSignature           = nDXUmsatzClassParmContract.parmUmsSignature();
                    TmpKumUmsCustAll.MonthYearSignature     = nDXUmsatzClassParmContract.parmMonthYearSignature();
                    tmpKumUmsCustAll.Party                  = custTablePartyId.Party;
                    TmpKumUmsCustAll.Alliance               = lAllianceValues ? accountNum : nDXUmsatzClassParmContract.parmSalesGroupId();
                    TmpKumUmsCustAll.Child                  = lAllianceValues ? accountNum : nDXUmsatzClassParmContract.parmSalesGroupId();
                    TmpKumUmsCustAll.SalesGroup             = nDXUmsatzClassParmContract.parmSalesGroupId();
                    TmpKumUmsCustAll.Company                = NDXCompanyBE::AllCompanies;
                    TmpKumUmsCustAll.insert();
                    tmpKumUmsCustAllStatus += ' (inserted)';
                }
                TmpKumUmsCustAll.anzChilds              = nDXUmsatzClassParmContract.parmNAnzChilds();
            }
            nAnz = 0;
            q    = new Query();
            qbds = q.addDataSource(tablenum(NDXTmpCustomerAlliance));
            qbds.addRange(fieldnum(nDXTmpCustomerAlliance, UmsSignature)).value(nDXUmsatzClassParmContract.parmUmsSignature());

            l_Alliance  = lAllianceValues ? accountNum : nDXUmsatzClassParmContract.parmSalesGroupId();
            if (lAllianceValues)
            {
                if (custTablePartyId)
                {
                    qbds.addRange(fieldnum(NDXTmpCustomerAlliance, AllianceParty)).value(queryValue(custTablePartyId.Party));
                }
                else
                {
                    qbds.addRange(fieldnum(NDXTmpCustomerAlliance, Alliance)).value(l_Alliance);
                }
            }
            else
            {
                qbds.addRange(fieldnum(NDXTmpCustomerAlliance, Alliance)).value(l_Alliance);
            }
            for (i=1; i <= conlen(conFirmen); i++)
            {
                qbds.addRange(fieldnum(nDXTmpCustomerAlliance, Company)).value(QueryValue(conpeek(conFirmen, i)));
            }
            qr = new QueryRun(q);

            anzDebitor = 0;
            while (qr.next())
            {
                nDXTmpCustomerAlliance = qr.get(tablenum(NDXTmpCustomerAlliance));

                // Kundennummern je Firma
                if (lAllianceValues)
                {
                    if (nDXUmsatzClassParmContract.parmFirma() == NDXCompanyBE::AllCompanies ||
                    nDXUmsatzClassParmContract.parmFirma() == NDXCompanyBE::WithoutAssignment)
                    {
                        lfirma = NDXCompanyBE::Niedax;
                    }
                    else
                    {
                        lfirma = nDXUmsatzClassParmContract.parmFirma();
                    }
                    accountNumPerCompany = NDXKumUmsCustWithSales::find(nDXUmsatzClassParmContract.parmLGetDataPerChild() ? nDXTmpCustomerAlliance.CustAccount : accountNum,
                    NDXHelperCommon::NDXCompanys2CompanyId(nDXUmsatzClassParmContract.parmLGetDataPerChild() ? nDXTmpCustomerAlliance.Company : lfirma)).getAccountNumPerCompany();
                }
                lfirma = nDXTmpCustomerAlliance.Company;

                conCompanies    = connull();
                company         = NDXHelperCommon::NDXCompanys2CompanyId(lfirma);
                conCompanies    += company;

                accountNumSearch    = nDXUmsatzClassParmContract.parmLGetDataPerChild() ? nDXTmpCustomerAlliance.CustAccount : (lAllianceValues ? accountNum : nDXUmsatzClassParmContract.parmSalesGroupId());

                if (lAllianceValues)
                {
                    if (accountNumPerCompany.exists(company))
                    {
                        accountNumSearch = accountNumPerCompany.lookup(company);
                    }
                }

                // falls Auswertung über Verkaufsbereich, Prüfung ob Debitor in der Firma dem Verkaufsbereich zugeordnet ist
                if (!nDXUmsatzClassParmContract.parmLAlliance() && nDXUmsatzClassParmContract.parmLSalesGroupMaster()
                    && !NDXUmsSalesGroupMember::existsAccountInSalesGroup(nDXTmpCustomerAlliance.CustAccount, nDXUmsatzClassParmContract.parmSalesGroupId(), lfirma))
                {
                    continue;
                }
                partyIdAlliance = custTablePartyId.Party;
                //TODO: DebuC NoParty
                if (!partyIdAlliance)
                {
                    partyIdAlliance = 0;
                }

                if (lAllianceValues)
                {
                    TmpKumUmsCust = NDXTmpKumUmsCust::find(
                        nDXUmsatzClassParmContract.parmUmsSignature(),
                        nDXUmsatzClassParmContract.parmMonthYearSignature(),
                        accountNumSearch, lfirma,
                        nDXUmsatzClassParmContract.parmLGetDataPerChild() ? nDXTmpCustomerAlliance.CustAccount : accountNum, partyIdAlliance, true);

                    tmpKumUmsCustStatus = strFmt('Seek Signature [%1] MonthYear [%2] Account [%3] Company [%4] found [%5]',
                        nDXUmsatzClassParmContract.parmUmsSignature(),
                        nDXUmsatzClassParmContract.parmMonthYearSignature(),
                        accountNumSearch, lfirma, TmpKumUmsCust.RecId > 0);
                }
                else
                {
                    TmpKumUmsCust = NDXTmpKumUmsCust::findSalesGroup(
                        nDXUmsatzClassParmContract.parmUmsSignature(),
                        nDXUmsatzClassParmContract.parmMonthYearSignature(),
                        accountNumSearch, lfirma, nDXUmsatzClassParmContract.parmSalesGroupId(), true);

                    tmpKumUmsCustStatus = strFmt('Seek Signature [%1] MonthYear [%2] Account [%3] Company [%4] found [%5]',
                        nDXUmsatzClassParmContract.parmUmsSignature(),
                        nDXUmsatzClassParmContract.parmMonthYearSignature(),
                        accountNumSearch, lfirma, TmpKumUmsCust.RecId > 0);
                }

                if (TmpKumUmsCust == null)
                {
                    custTableChild = CustTable::NDXfindCustByFirma(accountNumSearch, lfirma);
                    tmpKumUmsCust.Party                 = partyIdAlliance;
                    TmpKumUmsCust.Alliance              = lAllianceValues ? accountNum : nDXUmsatzClassParmContract.parmSalesGroupId();
                    TmpKumUmsCust.SalesGroup            = nDXUmsatzClassParmContract.parmSalesGroupId();
                    TmpKumUmsCust.Child                 = accountNumSearch;
                    TmpKumUmsCust.SalesGroupChild       = custTableChild.SalesGroup;
                    TmpKumUmsCust.PartyChild            = custTableChild.Party;
                    TmpKumUmsCust.Company                 = lfirma;
                    TmpKumUmsCust.UmsSignature          = nDXUmsatzClassParmContract.parmUmsSignature();
                    TmpKumUmsCust.MonthYearSignature    = nDXUmsatzClassParmContract.parmMonthYearSignature();
                    TmpKumUmsCust.insert();
                    tmpKumUmsCustStatus += ' (inserted)';
                }
                TmpKumUmsCust.anzChilds             = nDXUmsatzClassParmContract.parmNAnzChilds();

                // Umsatz des Customers des Rings
                kumUmsCust  = NDXKumUmsCust::find(lfirma, nDXTmpCustomerAlliance.CustAccount, nDXUmsatzClassParmContract.parmYearlfdJ());

                // Bonus des Customers des Rings
                kumBonCust  = NDXKumBonCust::find(lfirma, nDXTmpCustomerAlliance.CustAccount, nDXUmsatzClassParmContract.parmYearlfdJ());

                // Umsatz aktuelles Jahr
                if (kumUmsCust || kumBonCust)
                {
                    if (nDXUmsatzClassParmContract.parmLCSIncl())
                    {
                        nDXCentralStoreDistributionTable = NDX_CentralStoreDistributionTable::findCSAktive(nDXTmpCustomerAlliance.CustAccount, conCompanies);
                    }
                    // Falls es sich beim aktuellen Customer in _firma um ein Zentrallager handelt, darf dies nicht betrachtet werden.
                    if (!nDXUmsatzClassParmContract.parmLCSIncl()                            ||
                        !nDXCentralStoreDistributionTable  ||
                        (nDXCentralStoreDistributionTable.CentralStoreId == nDXTmpCustomerAlliance.CustAccount && !nDXUmsatzClassParmContract.parmLGetDataOnly()))
                    {
                        TmpKumUmsCust.addUmsLfdJ(kumUmsCust, kumBonCust);
                        if (lgetDataForAllCompanies)
                        {
                            TmpKumUmsCustAll.addUmsLfdJ(kumUmsCust, kumBonCust);
                        }
                    }
                }

                // Umsatz Vorjahr
                kumUmsCust  = NDXKumUmsCust::find(lfirma, nDXTmpCustomerAlliance.CustAccount, nDXUmsatzClassParmContract.parmYearVJ());
                kumBonCust  = NDXKumBonCust::find(lfirma, nDXTmpCustomerAlliance.CustAccount, nDXUmsatzClassParmContract.parmYearVJ());
                if (kumUmsCust || kumBonCust)
                {
                    if (nDXUmsatzClassParmContract.parmLCSIncl())
                    {
                        nDXCentralStoreDistributionTable = NDX_CentralStoreDistributionTable::findCSYearBest(nDXTmpCustomerAlliance.CustAccount, nDXUmsatzClassParmContract.parmYearVJ(), conCompanies);
                    }
                    // Falls es sich beim aktuellen Customer in _firma um ein Zentrallager handelt, darf dies nicht betrachtet werden.
                    if (!nDXUmsatzClassParmContract.parmLCSIncl() ||
                        !nDXCentralStoreDistributionTable  ||
                        (nDXCentralStoreDistributionTable.CentralStoreId == accountNum && !nDXUmsatzClassParmContract.parmLGetDataOnly()))
                    {
                        TmpKumUmsCust.addUmsVJ(kumUmsCust, kumBonCust);
                        if (lgetDataForAllCompanies)
                        {
                            TmpKumUmsCustAll.addUmsVJ(kumUmsCust, kumBonCust);
                        }
                    }
                }
                TmpKumUmsCust.write();

                ++anzDebitor;
                if ((anzDebitor mod 10) == 0)
                {
                    if (nDXUmsatzClassParmContract.parmLThread())
                    {
                        text = strfmt("@NDX:NDXCustomerSalesVolumeDetermination", NDXHelperCommon::seconds2Str(), anzDebitor, nDXTmpCustomerAlliance.CustAccount);   // [%1] Kunden-Umsatzermittlung: Anzahl [%2] Debitor [%3]
                        NDXTmpUmsatzClassThreadControl::setInfoStatic(nDXTmpUmsatzClassThreadControl, text, true);
                    }
                }
            }
            if (lgetDataForAllCompanies)
            {
                TmpKumUmsCustAll.write();
            }
            ttscommit;
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry10)
            {
                errorStr = strFmt("@NDXBase:NDXDeadLock", tableId2Name(tmpKumUmsCustAll.TableId)) + NDXGlobalConstants::NewLine;
                errorStr += tmpKumUmsCustAllStatus + NDXGlobalConstants::NewLine;
                errorStr += tmpKumUmsCustStatus + NDXGlobalConstants::NewLine;
                errorStr += NDXHelperCommon::callStack2str();
                throw Error(errorStr);
            }
            else
            {
                sleep(RandomGenerate::construct().randomInt(NDXExceptionConstants::RetryInterval500, NDXExceptionConstants::RetryInterval1000));
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry10)
            {
                errorStr = strFmt("@NDXBase:NDXUpdateConflict", tableId2Name(tmpKumUmsCustAll.TableId)) + NDXGlobalConstants::NewLine;
                errorStr += tmpKumUmsCustAllStatus + NDXGlobalConstants::NewLine;
                errorStr += tmpKumUmsCustStatus + NDXGlobalConstants::NewLine;
                errorStr += NDXHelperCommon::callStack2str();

                throw Error(errorStr);
            }
            else
            {
                sleep(RandomGenerate::construct().randomInt(NDXExceptionConstants::RetryInterval500, NDXExceptionConstants::RetryInterval1000));
                retry;
            }
        }
        catch (ex)
        {
            errorStr = ex.Message + NDXGlobalConstants::NewLine;
            if (TmpKumUmsCustAll)
            {
                errorStr += strFmt("@NDX:NDXTmpKumUmsCustInsertError",
                    'TmpKumUmsCustAll', tableId2Name(TmpKumUmsCustAll.TableId), TmpKumUmsCustAll.UmsSignature, 
                    TmpKumUmsCustAll.MonthYearSignature, TmpKumUmsCustAll.Child, TmpKumUmsCustAll.Company, TmpKumUmsCustAll.Alliance) + NDXGlobalConstants::NewLine;
            }
            if (tmpKumUmsCust)
            {
                errorStr += strFmt("@NDX:NDXTmpKumUmsCustInsertError",
                    'TmpKumUmsCust', tableId2Name(tmpKumUmsCust.TableId), tmpKumUmsCust.UmsSignature,
                    tmpKumUmsCust.MonthYearSignature, tmpKumUmsCust.Child, tmpKumUmsCust.Company, tmpKumUmsCust.Alliance) + NDXGlobalConstants::NewLine;
            }
            errorStr += NDXHelperCommon::callStack2str();
            throw Error(errorStr);
        }

        text = strfmt("@NDX:NDXDetermineMonthlySalesVolumeOfCustomer",
                   NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())),
                    nDXUmsatzClassParmContract.parmLAlliance() ? NDXUmsatzConstants::Verbandstruktur : NDXUmsatzConstants::Verkaufsbereich,
                    nDXUmsatzClassParmContract.parmLAlliance() ? accountNum       : nDXUmsatzClassParmContract.parmSalesGroupId(),
                    NDXUmsatzConstants::Ende, NDXUmsatzConstants::leer);  //[%1] %4: %5Monatsumsätze der Kunden für %3 [%2] ermitteln

        if (nDXUmsatzClassParmContract.parmLwithProt())
        {
            NDXUmsatzProt::add(nDXUmsatzClassParmContract.parmUmsSignature(), text, NDXProtStart::Stop);
        }
        if (nDXUmsatzClassParmContract.parmLThread())
        {
            NDXTmpUmsatzClassThreadControl::setInfoStatic(nDXTmpUmsatzClassThreadControl, text);
        }

    }

    // Umsätze kumuliert aufbereiten für Darstellung in Form
    if (!nDXUmsatzClassParmContract.parmLGetDataOnly())
    {
        NDXUmsatzClassThread::setValues4Form(
            nDXUmsatzClassParmContract.parmUmsSignature(),
            nDXUmsatzClassParmContract.parmMonthYearSignature(),
            accountNum,
            nDXUmsatzClassParmContract.parmFirma(), conFirmen, nDXUmsatzClassParmContract.parmLwithProt());
    }
    if (nDXUmsatzClassParmContract.parmLThread())
    {
        nDXThreadControl.stop();
    }
    return;
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "umsSignature">NDXUmsSignature</param>
/// <param name = "monthYearSignature">NDXMonthYearSignature</param>
/// <param name = "accountNum">AccountNum</param>
/// <param name = "firma">NDXCompanyBE</param>
/// <param name = "conFirmen">container</param>
/// <param name = "_lWithProt">boolean</param>
/// <param name = "umsSignatureForm">NDXUmsSignature</param>
static server void setValues4Form(NDXUmsSignature            umsSignature,
                              NDXMonthYearSignature      monthYearSignature,
                              AccountNum                  accountNum,
                              NDXCompanyBE                 firma,
                              container                   conFirmen,
                              boolean                     _lWithProt,
                              NDXUmsSignature            umsSignatureForm = umsSignature)
{
    NDXTmpKumUmsCust                   TmpKumUmsCust;//, TmpKumUmsCustEmpty;
    NDXKumUmsCustMonat                 kumUmsCustMonat;

    Map                         mapAccountNumPerUK;
    MapIterator                 mi;
    int                         j;
    str                         strQuery, strQuery2;
    Query                       q;
    QueryBuildDataSource        qbds;
    QueryRun                    qr;
    NDXCompanyBE                lfirma;        
    ;
    if (_lWithProt)
    {
        NDXUmsatzProt::add(umsSignature, "@NDX:NDXPrepareCumulativeCustomerMonthlySalesVolume", NDXProtStart::Start);            // Kundenmonatsumsatz für Form kumuliert aufbereiten
    }

    // Initialisierung
    ttsbegin;
    while select forUpdate  kumUmsCustMonat
    where               kumUmsCustMonat.UmsSignature == umsSignatureForm
    {
        kumUmsCustMonat.initUms();
        kumUmsCustMonat.initUmsCS();
        if (kumUmsCustMonat.validateWrite())
        {
            kumUmsCustMonat.update();
        }
    }
    ttscommit;        


    q = new Query();
    qbds = q.addDataSource(tablenum(NDXTmpKumUmsCust));

    lfirma = firma == NDXCompanyBE::AllCompanies ? NDXCompanyBE::Niedax : firma;
    mapAccountNumPerUK = NDXKumUmsCustWithSales::find(accountNum, NDXHelperCommon::NDXCompanys2CompanyId(lfirma)).getAccountNumPerCompany(false);

    if (mapAccountNumPerUK.elements())
    {
        mapAccountNumPerUK.insert(NDXCompanyBE::AllCompanies, accountNum);
        strQuery = strfmt('((%1.%2 = "%3") && (%1.%4 = "%5"))',
               qbds.name(),
               fieldstr(NDXTmpKumUmsCust, UmsSignature),
               umsSignature,
               fieldstr(NDXTmpKumUmsCust, MonthYearSignature),
               monthYearSignature);
        mi = new MapIterator(mapAccountNumPerUK);
        j  = 0;
        strQuery2 = ' && (';
        while (mi.more())
        {
            lfirma = mi.key();
            if (!confind(conFirmen, lfirma) && lfirma != NDXCompanyBE::AllCompanies)
            {
                mi.next();
                continue;
            }
            ++j;
            if (j > 1)
            {
                strQuery2 += ' || ';
            }
            strQuery2 += strfmt('((%1.%2 = %3) && (%1.%4 = "%5"))',
                    qbds.name(),
                    fieldstr(NDXTmpKumUmsCust, Company),
                    mi.key(),
                    fieldstr(NDXTmpKumUmsCust, Child),
                    mi.value());
            mi.next();
        }
        strQuery2 += ')';
        strQuery += strQuery2;
        qbds.addRange(fieldnum(NDXTmpKumUmsCust, RecId)).value(strQuery);
    }
    else
    {
        qbds.addRange(fieldnum(NDXTmpKumUmsCust, UmsSignature)).value(umsSignature);
        qbds.addRange(fieldnum(NDXTmpKumUmsCust, MonthYearSignature)).value(monthYearSignature);
        qbds.addRange(fieldnum(NDXTmpKumUmsCust, Child)).value(accountNum);
    }

    qr = new QueryRun(q);
    while (qr.next())
    {
        TmpKumUmsCust = qr.get(tablenum(NDXTmpKumUmsCust));
        NDXKumUmsCustMonat::Ums(TmpKumUmsCust, umsSignatureForm, TmpKumUmsCust.Company);
    }

    if (_lWithProt)
    {
        NDXUmsatzProt::add(umsSignature, "@NDX:NDXPrepareCumulativeCustomerMonthlySalesVolume", NDXProtStart::Stop);             // Kundenmonatsumsatz für Form kumuliert aufbereiten
    }
}

/// <summary>
/// DebuC 22.09.23
/// last modified: PaffH 01.03.25
/// </summary>
/// <param name = "_parm">container</param>
private server static void runGetValuesCSHandler(container _parm)
{
    System.Exception ex;
    NDXTmpUmsatzClassThreadControl nDXTmpUmsatzClassThreadControl;
    NDXUmsatzClassParmContract nDXUmsatzClassParmContract = NDXUmsatzClassParmContract::contractFromCon2Dim(_parm);
    try
    {   
        Integer logPointBegin = infologLine();

        infolog.parmRaiseInfologMessageEvent(Exception::Info, true);
        infolog.onMessageAdd += eventhandler(NDXBatchProcessingTable_tbl_EventHandler::onInfologMessageAdd);

        //if (lThread.cancelJob())
        //{
        //    NDXTmpUmsatzClassThreadControl::ThreadStop(NDXThreadTypes::getValuesCS, umsSignature);
        //    lThread.statusCounter(NDXThreadConstants::StatusCounterCancel);                
        //}

        nDXTmpUmsatzClassThreadControl = NDXTmpUmsatzClassThreadControl::ThreadStart(NDXThreadTypes::getValuesCS, nDXUmsatzClassParmContract);
        NDXUmsatzClassThread::getValuesCS(_parm);
        NDXTmpUmsatzClassThreadControl::ThreadStop(NDXThreadTypes::getValuesCS, nDXUmsatzClassParmContract.parmUmsSignature());
        //lThread.statusCounter(NDXThreadConstants::StatusCounterOK);            

        Integer logPointNow = infologLine();
        if (logPointBegin + 1 <= logPointNow)
        {
            container conInfoLog = infolog.cut(logPointBegin + 1, logPointNow);
            NDXThread::saveInfo2Thread(
                nDXUmsatzClassParmContract.parmProcessSignature(),
                classstr(NDXUmsatzClassThread),
                staticmethodstr(NDXUmsatzClassThread, getValuesCS),
                conInfoLog,
                nDXUmsatzClassParmContract.parmRecIdNDXBatchProcessingTable());
        }
    }
    catch (ex)
    {
        NDXThread::saveError2Thread(
            nDXUmsatzClassParmContract.parmProcessSignature(), 
            classstr(NDXUmsatzClassThread), 
            staticmethodstr(NDXUmsatzClassThread, getValuesCS), 
            ex,
            nDXUmsatzClassParmContract.parmRecIdNDXBatchProcessingTable());
    }        

}

/// <summary>
/// DebuC 22.09.23
/// last modified: PaffH 17.02.25
/// </summary>
/// <param name = "inputParm">Container</param>
static server void getValuesCS(Container inputParm)
{
    #AviFiles
    #define.lfdJahr(1)
    #define.VorJahr(2)

    NDXTmpCSAlliance                   nDX_TmpCSAlliance;
    NDX_CentralStoreDistributionTable   nDX_CentralStoreDistributionTable;
    NDX_CentralStoreDistributionLine    nDX_CentralStoreDistributionLine;
    NDXTmpCustomerAlliance             nDX_TmpCustomerAlliance;
    NDXTmpUmsatzClassThreadControl     nDXTmpUmsatzClassThreadControl;
    NDXThreadControl                   nDXThreadControl;
    NDXJobMangerJobsClass              nDX_JobManagerJobs;
    container                   conCompanies = connull();
    AccountNum                  accountNum;
    NDXUmsSignature             umsSignature;
    NDXMonthYearSignature       monthYearSignature;
    NDXYear                     yearlfdJ, yearVJ;
    int                         i, j, k;
    int                         conLen;
    boolean                     lWithProt;
    CompanyId                   company;
    boolean                     lGetDataOnly;
    boolean                     lUseCalculatedData;
    boolean                     lThread;
    boolean                     lAlliance;
    CommissSalesGroup           salesGroup;
    boolean                     lSalesGroupMaster;
    str                         text;
    NDXUmsatzClass              nDXUmsatzClass;
    NDXGetUmsType               umsType;
    NDXUmsatzClassArgs          args = new NDXUmsatzClassArgs();
    boolean                     lAllianceValues;
    boolean                     lActiveSet;
    accountNum                  l_Alliance;
    container                   conCS;
    NDXCentralStoreId          centralStoreId;
    Query                       q;
    QueryRun                    qr;
    QueryBuildDataSource        qbds;
    SysOperationProgress        progress;
    int                         total, total1;
    str                         actionStr;
    int                         counter1;        
    Map                         mapAccountNumPerUK;
    CustAccount                 accountNumUK;        
    RefRecId                    dirPartyIdCalculated;
    NDXSignature                processSignature;

    const str constUmsSignature         = 'UmsSignature';
    const str constAccountNum           = 'AccountNum';
    const str constYearlfdJ             = 'YearlfdJ';
    const str constYearVJ               = 'YearVJ';
    const str constConLenCompanies      = 'ConLenCompanies';
    const str constConCompanies         = 'ConCompanies';
    const str constMonthYearSignature   = 'MonthYearSignature';
    const str constLwithProt            = 'LwithProt';
    const str constLGetDataOnly         = 'LGetDataOnly';
    const str constlUseCalculatedData   = 'lUseCalculatedData';
    const str constLThread              = 'LThread';
    const str constlAlliance            = 'lAlliance';
    const str constSalesGroupId         = 'SalesGroupId';
    const str constSalesGroupMaster     = 'SalesGroupMaster';
    const str constProcessSignature     = 'ProcessSignature';
    container                   conParm;
    int                         ci;
    ;

    umsType = NDXGetUmsType::WithoutDefiniton;

    args.parmEnumType(enumnum(NDXGetUmsType));
    args.parmEnum(enum2int(umsType));
    nDXUmsatzClass = nDXUmsatzClass::construct(args);


    // Parameter übernehmen
    for(ci = 1; ci<= conLen(inputParm);ci++)
    {
        conParm = conPeek(inputParm, ci);

        switch(conPeek(conParm, 1))
        {
            case constUmsSignature:
                umsSignature = conPeek(conParm, 2);
                break;
            case constAccountNum:
                accountNum = conPeek(conParm, 2);
                break;

            case constYearlfdJ:
                yearlfdJ = conPeek(conParm, 2);
                break;
            case constYearVJ:
                yearVJ = conPeek(conParm, 2);
                break;
            case constConLenCompanies:
                conLen = conPeek(conParm, 2);
                break;
            case constConCompanies:
                conCompanies = conPeek(conParm, 2);
                break;
            case constMonthYearSignature:
                monthYearSignature = conPeek(conParm, 2);
                break;
            case constLwithProt:
                lWithProt = conPeek(conParm, 2);
                break;
            case constLGetDataOnly:
                lGetDataOnly = conPeek(conParm, 2);
                break;
            case constlUseCalculatedData:
                lUseCalculatedData = conPeek(conParm, 2);
                break;
            case constlThread:
                lThread = conPeek(conParm, 2);
                break;
            case constlAlliance:
                lAlliance = conPeek(conParm, 2);
                break;
            case constSalesGroupId:
                salesGroup = conPeek(conParm, 2);
                break;
            case constSalesGroupMaster:
                lSalesGroupMaster = conPeek(conParm, 2);
                break;
            case constProcessSignature:
                processSignature = conPeek(conParm, 2);
                break;
        }
    }

    if (lAlliance)
    {
        actionStr = strfmt("@NDX:NDXAlliance", accountNum);                 // Verband [%1]
    }
    else
    {
        actionStr = strfmt("@NDX:NDXSalesDistrict", salesGroup);                 // Verkaufsbereich [%1]
    }
    nDX_JobManagerJobs = NDXJobMangerJobsClass::construct(NDXJobManagerJobId::getUmsVerband_L3);
    nDX_JobManagerJobs.start("@NDX:NDXDetermineSalesVolumeSharesOfCentralWarehouse", actionStr );       // // Umsatzanteile Zentrallager ermitteln


    lAllianceValues = NDXUmsatzClass::AllianceOrSalesGroupValues(lAlliance, lUseCalculatedData, lGetDataOnly, lSalesGroupMaster);

    text = strfmt("@NDX:NDXDetermineMonthlySalesVolumeOfCustomer",
               NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())),
                lAlliance ? NDXUmsatzConstants::Verbandstruktur : NDXUmsatzConstants::Verkaufsbereich,
               lAlliance ? accountNum       : salesGroup,
               NDXUmsatzConstants::Start, NDXUmsatzConstants::Zentrallager);  //[%1] %4: %5Monatsumsätze der Kunden für %3 [%2] ermitteln


    if (lThread)
    {
        nDXThreadControl.Signature     = processSignature;
        nDXThreadControl.ThreadSession = SessionId();
        nDXThreadControl.MethodName    = staticmethodstr(NDXUmsatzClassThread, getValuesCS);
        nDXThreadControl.ClassName     = classstr(NDXUmsatzClassThread);
        nDXThreadControl = NDXThreadControl::findOrCreate(nDXThreadControl);

        nDXTmpUmsatzClassThreadControl = NDXTmpUmsatzClassThreadControl::find(umsSignature, NDXThreadTypes::getValuesCS, true);
        //nDXTmpUmsatzClassThreadControl.setInfo(_Text);
        NDXTmpUmsatzClassThreadControl::setInfoStatic(nDXTmpUmsatzClassThreadControl, text);
    }

    nDX_JobManagerJobs.setAction("@NDX:NDXDeleteInvalidValues", strfmt('%1-%2-%3', umsSignature, monthYearSignature, l_Alliance));     // Ungültige Werte löschen
    try
    {

        l_Alliance  =   lAllianceValues ? accountNum : salesGroup;
        // if (lThread)
        {
            q       = new Query();
            qbds    = q.addDataSource(tablenum(NDXTmpCSAlliance));
            qbds.update(true);
            qbds.addRange(fieldnum(NDXTmpCSAlliance, UmsSignature)).value(umsSignature);
            qbds.addRange(fieldnum(NDXTmpCSAlliance, monthYearSignature)).value(monthYearSignature);
            qbds.addRange(fieldnum(NDXTmpCSAlliance, Exclude)).value(QueryValue(NoYes::No));
            qbds.addRange(fieldnum(NDXTmpCSAlliance, Alliance)).value(l_Alliance);                
            for (i=1; i <= conlen(conCompanies); i++)
            {
                qbds.addRange(fieldnum(NDXTmpCSAlliance, Company)).value(conpeek(conCompanies, i));
            }                
            qr      = new QueryRun(q);

            ttsbegin;
            while (qr.next())
            {
                nDX_TmpCSAlliance = qr.get(tablenum(NDXTmpCSAlliance));
                nDX_TmpCSAlliance.delete();
            }
            ttscommit;
        }
    }
    catch (exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= NDXConstants::RetryNum)
        {
            throw Exception::Deadlock;
        }
        else

        {
            retry;
        }
    }

    if (lWithProt)
    {
        NDXUmsatzProt::add(umsSignature, "@NDX:NDXDetermineSalesVolumeSharesOfCentralWarehouse", NDXProtStart::Start);            // Umsatzanteile Zentrallager ermitteln
    }

    NDXKumUmsCustArtGrp::InitUmsCS(nDX_TmpCSAlliance, false);

    lActiveSet = yearlfdJ == year(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()));
    q       = new Query();
    qbds    = q.addDataSource(tablenum(NDXTmpCustomerAlliance));
    qbds.addRange(fieldnum(nDXTmpCustomerAlliance, UmsSignature)).value(umsSignature);
    l_Alliance  = lAllianceValues ? accountNum : salesGroup;
    qbds.addRange(fieldnum(NDXTmpCustomerAlliance, Alliance)).value(l_Alliance);
    qr      = new QueryRun(q);

    if (!lThread && !lGetDataOnly)
    {
        progress    = SysOperationProgress::newMultiBar(2, #aviUpdate, "@NDX:NDXDetermineCentralWarehouseSalesVolume");     // ZL-Umsatz ermitteln
        total      = SysQuery::countTotal(qr);
        progress.setTotal(total, 1);
    }
    if (false)
    {
        throw error('Testfehlermeldung [NDXUmsatzClassThread::getValuesCS()]');
    }

    while (qr.next())
    {
        nDX_TmpCustomerAlliance = qr.get(tablenum(NDXTmpCustomerAlliance));
        dirPartyIdCalculated = nDX_TmpCustomerAlliance.CustParty;            // 1.11: NDX/PAFFH/NDX_TASK1235004221/03.02.2018
        if (lThread)
        {
            nDXTmpUmsatzClassThreadControl.incActiveCounter();
            text = strfmt("@NDX:NDXDetermineDistributionValues", NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())), nDX_TmpCustomerAlliance.CustAccount);
            NDXTmpUmsatzClassThreadControl::setInfoStatic(nDXTmpUmsatzClassThreadControl, text);
        }
        if (progress)
        {
            ++total1;
            progress.setCount(total1, 1);
            progress.setText(nDX_TmpCustomerAlliance.CustAccount, 1);
        }

        mapAccountNumPerUK = nDX_TmpCustomerAlliance.getAccountNumPerCompany();

        // Verteilungswerte für aktuelles Jahr
        for (i = 1; i <= conlen(conCompanies); i++)
        {
            company = conpeek(conCompanies,i);
            // wenn der Debitor in der company nicht vorhanden ist ...
            if (!mapAccountNumPerUK.exists(company))
            {
                continue;
            }
            changecompany(company)
            {
                nDX_CentralStoreDistributionTable   = null;
                nDX_CentralStoreDistributionLine    = null;
                nDX_TmpCSAlliance                   = null;

                // Ermittlung der auszuwertenden Zentrallager (CustAccount muss Eintrag in Line besitzen)
                accountNumUK = mapAccountNumPerUK.exists(company) ? mapAccountNumPerUK.lookup(company) : nDX_TmpCustomerAlliance.CustAccount;

                if ((select RecId from NDXTmpCustomerAlliance
                    where  NDXTmpCustomerAlliance.UmsSignature == umsSignature
                        && NDXTmpCustomerAlliance.Alliance == l_Alliance
                        && NDXTmpCustomerAlliance.Company == NDXHelperCommon::CompanyId2NDXCompany(company)
                        && NDXTmpCustomerAlliance.CustAccount == accountNumUK).RecId > 0)
                {
                    conCS = NDXCSD::getCentralStoresFromCustAccount(accountNumUK);
                }
                else if (lAlliance &&
                (select RecId from NDXTmpCustomerAlliance
                    where  NDXTmpCustomerAlliance.UmsSignature == umsSignature
                        && NDXTmpCustomerAlliance.Alliance == accountNumUK
                        && NDXTmpCustomerAlliance.Company == NDXHelperCommon::CompanyId2NDXCompany(company)
                        && NDXTmpCustomerAlliance.CustAccount == accountNumUK).RecId > 0)
                {
                    conCS = NDXCSD::getCentralStoresFromCustAccount(accountNumUK);
                }
                else
                {
                    conCS = connull();
                }

                for (k = 1; k <= conlen(conCS); ++k)
                {
                    centralStoreId  = conpeek(conCS, k);

                    // Verteilwert ermitteln (aktuelles Jahr + Vorjahr)
                    for (j = 1; j <= 2; ++j)
                    {
                        nDX_CentralStoreDistributionLine = NDXCSD::getCentralStoreDistribution4CustAccount(centralStoreId, accountNumUK, j == #lfdJahr ? yearlfdJ : yearVJ);
                        {
                            try
                            {
                                ++counter1;
                                nDX_JobManagerJobs.setAction("@NDX:NDXCentralWarehouseDistributionSet", strfmt('%1-%2-%3', nDX_TmpCustomerAlliance.Alliance, accountNumUK, centralStoreId), counter1);     // Zentrallager-Verteilsatz

                                nDX_TmpCSAlliance = NDXTmpCSAlliance::find(umsSignature,
                                                        monthYearSignature,
                                                        NoYes::No,
                                                        nDX_CentralStoreDistributionLine.dataAreaId,
                                                        nDX_TmpCustomerAlliance.Alliance,
                                                        accountNumUK,
                                                        centralStoreId, true);

                                ttsbegin;
                                if (!nDX_TmpCSAlliance)
                                {
                                    nDX_TmpCSAlliance.Alliance              = nDX_TmpCustomerAlliance.Alliance;
                                    nDX_TmpCSAlliance.CustAccount           = accountNumUK;
                                    nDX_TmpCSAlliance.UmsSignature          = umsSignature;
                                    nDX_TmpCSAlliance.MonthYearSignature    = monthYearSignature;
                                    nDX_TmpCSAlliance.Exclude               = NoYes::No;
                                    nDX_TmpCSAlliance.CentralStoreId        = centralStoreId;
                                    nDX_TmpCSAlliance.Company               = nDX_CentralStoreDistributionLine.dataAreaId;
                                }
                                if (j == #lfdJahr)
                                {
                                    nDX_TmpCSAlliance.CSDPctLfdJ            = nDX_CentralStoreDistributionLine.CSDPct;
                                }
                                else
                                {
                                    nDX_TmpCSAlliance.CSDPctVJ              = nDX_CentralStoreDistributionLine.CSDPct;
                                }

                                nDX_TmpCSAlliance.write();
                                ttscommit;
                            }
                            catch
                            {
                                throw Error(strfmt("@NDX:NDXCouldNotCreateRecordTmpCSAlliance", nDX_TmpCustomerAlliance.Alliance, nDX_TmpCustomerAlliance.CustAccount));     // Datensatz in NDX_TMPCSAlliance Alliance:[%1] CustAccount[%2] konnte nicht angelegt werden
                            }
                            // Artikelgruppenanteile ermitteln

                            if (j == #lfdJahr)
                            {
                                NDXKumUmsCustArtGrp::getUmsCS(nDX_TmpCSAlliance, yearlfdJ, false);
                            }
                            else
                            {
                                NDXKumUmsCustArtGrp::getUmsCS(nDX_TmpCSAlliance, yearVJ, false, false);
                            }

                        }
                    }
                }
            }
        }
    }
    if (progress)
    {
        progress.kill();
    }

    text = strfmt("@NDX:NDXDetermineCentralWarehouseSalesData", NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())));        //[%1] Zentrallager-Umsatzdaten ermitteln
    if (lWithProt)
    {
        NDXUmsatzProt::add(umsSignature, text, NDXProtStart::Start);
    }
    if (lThread)
    {            
        NDXTmpUmsatzClassThreadControl::setInfoStatic(nDXTmpUmsatzClassThreadControl, text);
    }        
    nDXUmsatzClass.parmAccountNum(lAllianceValues ? accountNum : salesGroup);
    nDXUmsatzClass.parmSalesGroupId(salesGroup);
    nDXUmsatzClass.parmYearlfdJ(yearlfdJ);
    nDXUmsatzClass.parmUmsSignature(umsSignature);
    nDXUmsatzClass.parmlAlliance(lAlliance);
    nDXUmsatzClass.parmLGetDataOnly(lGetDataOnly);
    nDXUmsatzClass.parmMonthYearSignature(false, monthYearSignature);
    NDXUmsatzClassThread::setValues4FormCS(nDXUmsatzClass);

    if (lWithProt)
    {
        NDXUmsatzProt::add(umsSignature, text, NDXProtStart::Stop);
    }


    // Artikelgruppenumsatz-ZL-Anteile den Artikelgruppenumsätzen zufügen
    text = strfmt("@NDX:NDXAddSalesVoumeShares", NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())));        //[%1] Artikelgruppenumsatz-ZL-Anteile den Artikelgruppenumsätzen zufügen
    if (lWithProt)
    {
        NDXUmsatzProt::add(umsSignature, text, NDXProtStart::Start);
    }
    if (lThread)
    {            
        NDXTmpUmsatzClassThreadControl::setInfoStatic(nDXTmpUmsatzClassThreadControl, text);
    }
    if (!lGetDataOnly && !lSalesGroupMaster)
    {    
        nDXUmsatzClass.parmPartyIdCalculated(dirPartyIdCalculated);
    }
    NDXTmpKumUmsCustArtGrp::setUmsatzCS(umsSignature, monthYearSignature, (lAllianceValues ? accountNum : salesGroup), lWithProt, nDXUmsatzClass);

    NDXKumUmsCustMonat::UmsCSAlleFirmen(umsSignature);
    if (lWithProt)
    {
        NDXUmsatzProt::add(umsSignature, text, NDXProtStart::Stop);
    }

    text = strfmt("@NDX:NDXDetermineMonthlySalesVolumeOfCustomer",
               NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())),
               lAllianceValues ? NDXUmsatzConstants::Verbandstruktur : NDXUmsatzConstants::Verkaufsbereich,
               lAllianceValues ? accountNum       : salesGroup,
               NDXUmsatzConstants::Ende, NDXUmsatzConstants::Zentrallager);  //[%1] %4: %5Monatsumsätze der Kunden für %3 [%2] ermitteln
    if (lWithProt)
    {
        NDXUmsatzProt::add(umsSignature, text, NDXProtStart::Stop);
    }
    if (lThread)
    {            
        NDXTmpUmsatzClassThreadControl::setInfoStatic(nDXTmpUmsatzClassThreadControl, text);
        nDXThreadControl.stop();
    }
    nDX_JobManagerJobs.ende();
    return;

}

