/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "accountNum">AccountNum</param>
/// <param name = "firma">NDXCompanys</param>
/// <returns>CustTable</returns>
static CustTable getCustTableFromAccount(AccountNum accountNum, NDXCompanys firma)
{
    NDXCompanys     lfirma;
    ;

    lfirma = firma;
    if (firma == NDXCompanyBE::AllCompanies ||
    firma == NDXCompanyBE::WithoutAssignment)
    {
        lfirma = NDXCompanyBE::Niedax;
    }

    return NDXKumUmsCustWithSales::custTableFromAccount(accountNum, lfirma);
}

/// <summary>
/// DebuC 22.09.23
/// last modified: PaffH 01.03.25
/// </summary>
/// <param name = "_parm">container</param>
private server static void runGetValuesCustHandler(container _parm)
{
    System.Exception ex;
    NDXUmsatzClassParmContract nDXUmsatzClassParmContract = NDXUmsatzClassParmContract::contractFromCon2Dim(_parm);
    NDXTmpUmsatzClassThreadControl nDXTmpUmsatzClassThreadControl;
    try
    {
        Integer logPointBegin = infologLine();

        infolog.parmRaiseInfologMessageEvent(Exception::Info, true);
        infolog.onMessageAdd += eventhandler(NDXBatchProcessingTable_tbl_EventHandler::onInfologMessageAdd);
        //if (t.cancelJob())
        //{
        //    NDXTmpUmsatzClassThreadControl::ThreadStop(NDXThreadTypes::getValuesCust, umsSignature);
        //    t.statusCounter(NDXThreadConstants::StatusCounterCancel);               
        //}

        nDXTmpUmsatzClassThreadControl = NDXTmpUmsatzClassThreadControl::ThreadStart(NDXThreadTypes::getValuesCust, nDXUmsatzClassParmContract);
        NDXUmsatzClassThread::getValuesCust(_parm);
        NDXTmpUmsatzClassThreadControl::ThreadStop(NDXThreadTypes::getValuesCust, nDXUmsatzClassParmContract.parmUmsSignature());
        //t.statusCounter(NDXThreadConstants::StatusCounterOK);

        Integer logPointNow = infologLine();
        if (logPointBegin + 1 <= logPointNow)
        {
            container conInfoLog = infolog.cut(logPointBegin + 1, logPointNow);
            NDXThread::saveInfo2Thread(
            nDXUmsatzClassParmContract.parmProcessSignature(),
            classstr(NDXUmsatzClassThread),
            staticmethodstr(NDXUmsatzClassThread, getValuesCust),
            conInfoLog,
            nDXUmsatzClassParmContract.parmRecIdNDXBatchProcessingTable());
        }
    }
    catch (ex)
    {
        NDXThread::saveError2Thread(
            nDXUmsatzClassParmContract.parmProcessSignature(), 
            classstr(NDXUmsatzClassThread), 
            staticmethodstr(NDXUmsatzClassThread, getValuesCust), 
            ex,
            nDXUmsatzClassParmContract.parmRecIdNDXBatchProcessingTable());
    }
}

