/// <summary>
/// DebuC 22.09.23
/// last modified: PaffH 24.05.25
/// </summary>
/// <param name = "inputParm">Container</param>
static server void getValuesArtGrp(Container inputParm)
{
    #AviFiles

    NDXTmpKumUmsCustArtGrp             tmpKumUmsCustArtGrp;
    NDXTmpKumUmsCustArtGrp             tmpKumUmsCustArtGrpAll, tmpKumUmsCustArtGrpDeb;
    NDXTmpCustomerAlliance             nDX_TmpCustomerAlliance;
    NDXKumUmsCustArtGrp                kumUmsCustArtGrp;
    NDXArtGrp                          nDX_ArtGrp;
    NDXTmpUmsatzClassThreadControl     nDXTmpUmsatzClassThreadControl;
    NDXThreadControl                   nDXThreadControl;
    //NDX_RLSCompany                      nDX_RLSCompany, nDX_RLSCompanyRecord;
    NDX_CentralStoreDistributionTable   nDX_CentralStoreDistributionTable;
    CustTable                           custTablePartyId;
    CustTable                           custTablePartyId2; 


    //AccountNum                  accountNum;
    AccountNum                  l_Child;
    NDXUmsSignature             umsSignature;
    NDXMonthYearSignature       monthYearSignature;
    NDXYear                     yearlfdJ, yearVJ;
    boolean                     lWithProt;
    boolean                     lUseCalculatedData;
    boolean                     lGetDataOnly;
    boolean                     lThread;
    boolean                     lCSIncl;
    boolean                     lSalesGroupMaster;
    boolean lgetDataForAllCompanies = false;
    NDXItemGroup                ArtGrp;
    str                         text;
    //int                         threadSession;
    int                         i, l_conLen;
    container                   conCompanys = connull();
    //CompanyId                   company;
    //container                   conRLSFirma;
    boolean                     lProcessData;
    boolean                     lAlliance;
    CommissSalesGroup           salesGroupId;
    boolean                     lAllianceValues;
    NDXAlliance                 l_Alliance;

    Query                       q, qCustomer, q2;
    QueryRun                    qr, qrCustomer, qr2;
    QueryBuildDataSource        qbds, qbdsCustomer, qbds2;
    NDXUmsatzClassArgs          args = new NDXUmsatzClassArgs();
    NDXUmsatzClass              nDX_UmsatzClass;
    NDXNoYesBE                  lBasisUmsLfdJ;
    NDXGetUmsType               umsType;
    SysOperationProgress        progress;
    int                         total, total1, total2;
    //Map                         mapAccountNumPerUK;
    //MapIterator                 mi;
    //str                         strQuery, strQuery2;
    //int                         j;
    NDXCompanyBE                firma;
    NDXJobMangerJobsClass       nDX_JobManagerJobs;
    str                         actionStr;
    int                         counter1;
    //CompanyId                   _company;
    NDXCompanyBE                lFirma;
    boolean                     lInfo = false;
    boolean                     lMasterAlliance;
