            NDXUmsatzProt::add(umsSignature, text, NDXProtStart::Start);
        }

        try
        {
            // auszuwertende Debitoren ermitteln
            qCustomer       = new Query();
            qbdsCustomer    = qCustomer.addDataSource(tablenum(NDXTmpCustomerAlliance));
            qbdsCustomer.addRange(fieldnum(NDXTmpCustomerAlliance, UmsSignature)).value(umsSignature);

            //if (lAllianceValues)
            //{
            //    qbdsCustomer.addRange(fieldnum(nDXTmpCustomerAlliance, AllianceParty)).value(queryValue(custTablePartyId.Party));
