                        qbds2.addRange(fieldnum(NDXTmpKumUmsCustArtGrp, UmsSignature))         .value(umsSignature);
                        qbds2.addRange(fieldnum(NDXTmpKumUmsCustArtGrp, MonthYearSignature))   .value(monthYearSignature);
                        qbds2.addRange(fieldnum(NDXTmpKumUmsCustArtGrp, Alliance))             .value(l_Alliance);
                        qbds2.addRange(fieldnum(NDXTmpKumUmsCustArtGrp, PartyChild)).value(queryValue(NDXUmsatzClass::getCustTableFromAccount(nDX_TmpCustomerAlliance.CustAccount, nDX_TmpCustomerAlliance.Company).Party));
