                        {
                            infoAddition = strFmt("@NDX:NDXErrorTmpKumUmsCustArtGrpAddition", sessionId(), tmpKumUmsCustArtGrp.Alliance, tmpKumUmsCustArtGrp.Child, tmpKumUmsCustArtGrp.ItemGroup, tmpKumUmsCustArtGrp.UmsSignature, tmpKumUmsCustArtGrp.MonthYearSignature);
                            infoAddition += " NDXUmsatzClassThread:2035";
                            throw Error(strFmt("@NDXBase:NDXDeadLock", tableId2Name(tmpKumUmsCustArtGrp.TableId)) + infoAddition);
                        }
                        else
                        {
                            sleep(NDXExceptionConstants::RetryInterval500);
                            retry;
                        }
                    }
                    catch (Exception::UpdateConflict)
                    {
                        if (xSession::currentRetryCount() >= NDXExceptionConstants::Retry5)
                        {
                            infoAddition = strFmt("@NDX:NDXErrorTmpKumUmsCustArtGrpAddition", sessionId(), tmpKumUmsCustArtGrp.Alliance, tmpKumUmsCustArtGrp.Child, tmpKumUmsCustArtGrp.ItemGroup, tmpKumUmsCustArtGrp.UmsSignature, tmpKumUmsCustArtGrp.MonthYearSignature);
                            infoAddition += " NDXUmsatzClassThread:2049";
                            throw Error(strFmt("@NDXBase:NDXUpdateConflict", tableId2Name(tmpKumUmsCustArtGrp.TableId)) + infoAddition);
                        }
                        else
                        {
                            sleep(NDXExceptionConstants::RetryInterval500);
                            retry;
                        }
