                        tmpKumUmsCustArtGrpDeb = NDXTmpKumUmsCustArtGrp::find(umsSignature,
                                                                            monthYearSignature,
                                                                            l_Alliance,
                                                                            nDX_TmpCustomerAlliance.CustAccount,
                                                                            kumUmsCustArtGrp.Companys,
                                                                            ArtGrp,
                                                                            true, true);

                        if (tmpKumUmsCustArtGrpDeb == null)
                        {                                    
                            tmpKumUmsCustArtGrpDeb.Party                = custTablePartyId.Party;
                            tmpKumUmsCustArtGrpDeb.Alliance             = l_Alliance;
                            tmpKumUmsCustArtGrpDeb.SalesGroup         = salesGroupId;

                            if (lGetDataOnly)
                            {
                                tmpKumUmsCustArtGrpDeb.Child                = nDX_TmpCustomerAlliance.CustAccount;
                                tmpKumUmsCustArtGrpDeb.PartyChild         = nDX_TmpCustomerAlliance.CustParty;
                            }
                            else                            
                            {                                        
                                tmpKumUmsCustArtGrpDeb.Child                = custTablePartyId2.AccountNum;
                                tmpKumUmsCustArtGrpDeb.PartyChild           = custTablePartyId2.Party;                                        
                            }

                            tmpKumUmsCustArtGrpDeb.Company              = kumUmsCustArtGrp.Companys;
                            tmpKumUmsCustArtGrpDeb.UmsSignature         = umsSignature;
                            tmpKumUmsCustArtGrpDeb.MonthYearSignature   = monthYearSignature;
                            tmpKumUmsCustArtGrpDeb.ItemGroup            = ArtGrp;
                            tmpKumUmsCustArtGrpDeb.Name                 = nDX_ArtGrp.BEZ;
                            if (tmpKumUmsCustArtGrpDeb.validateWrite())
                            {
                                tmpKumUmsCustArtGrpDeb.insert();
                            }
                        }
                    }

                    if (lgetDataForAllCompanies)
                    {
                        // Alle Firmen
                        if (lGetDataOnly)
                        {
                            tmpKumUmsCustArtGrpAll = NDXTmpKumUmsCustArtGrp::find(umsSignature,
                                                                            monthYearSignature,
                                                                            l_Alliance,
                                                                            nDX_TmpCustomerAlliance.CustAccount,
                                                                            NDXCompanyBE::AllCompanies,
                                                                            ArtGrp, true, true);
                        }
                        else
                        {
                            if (lAllianceValues)
                            {
                                tmpKumUmsCustArtGrpAll = NDXTmpKumUmsCustArtGrp::findPartyId(umsSignature,
                                                                                monthYearSignature,
                                                                                custTablePartyId.Party,
                                                                                NDXCompanyBE::AllCompanies,
                                                                                ArtGrp, true, true);
                            }
                            else
                            {
                                tmpKumUmsCustArtGrpAll = NDXTmpKumUmsCustArtGrp::find(umsSignature,
                                                                                monthYearSignature,
                                                                                l_Alliance,
                                                                                l_Child,
                                                                                NDXCompanyBE::AllCompanies,
                                                                                ArtGrp, true, true);
                            }
