                        if (tmpKumUmsCustArtGrpAll == null)
                        {
                            tmpKumUmsCustArtGrpAll.Party              = custTablePartyId.Party;
                            tmpKumUmsCustArtGrpAll.Alliance             = l_Alliance;

                            if (lGetDataOnly)
                            {
                                tmpKumUmsCustArtGrpAll.Child                = nDX_TmpCustomerAlliance.CustAccount;
                                tmpKumUmsCustArtGrpAll.PartyChild         = nDX_TmpCustomerAlliance.CustParty;
                            }
                            else

                            {

                                if (lAllianceValues)                            // 1.20: NDX/PAFFH/NDX_TASK1235004254/21.04.2018
                                {
                                    tmpKumUmsCustArtGrpAll.Child                = custTablePartyId2.AccountNum;
                                    tmpKumUmsCustArtGrpAll.PartyChild         = custTablePartyId2.Party;
                                }

                                else
                                {
                                    tmpKumUmsCustArtGrpAll.Child                = l_Child;
                                }

                            }
                            tmpKumUmsCustArtGrpAll.SalesGroup         = salesGroupId;
                            tmpKumUmsCustArtGrpAll.Company              = NDXCompanyBE::AllCompanies;
                            tmpKumUmsCustArtGrpAll.UmsSignature         = umsSignature;
                            tmpKumUmsCustArtGrpAll.MonthYearSignature   = monthYearSignature;
                            tmpKumUmsCustArtGrpAll.ItemGroup            = ArtGrp;
                            tmpKumUmsCustArtGrpAll.Name                 = nDX_ArtGrp.BEZ;
                            if (tmpKumUmsCustArtGrpAll.validateWrite())
                            {
                                tmpKumUmsCustArtGrpAll.insert();
                            }
                        }
                    }

                    // Einzelner Debitor

                    if (lAllianceValues && !lGetDataOnly)   // HP 27.04.18 - darf nicht im Fall getDataOnly durchlaufen!!!                            
                    {                                
                        tmpKumUmsCustArtGrp = NDXTmpKumUmsCustArtGrp::findPartyId(umsSignature,
                                                                    monthYearSignature,
                                                                    custTablePartyId.Party,
                                                                    kumUmsCustArtGrp.Companys,
                                                                    ArtGrp, true, true);
                    }
                    else
                    {
                        if (lAllianceValues || lGetDataOnly)
                        {
                            tmpKumUmsCustArtGrp = NDXTmpKumUmsCustArtGrp::find(umsSignature,
                                                                        monthYearSignature,
                                                                        l_Alliance,
                                                                        kumUmsCustArtGrp.CustAccount,
                                                                        kumUmsCustArtGrp.Companys,
                                                                        ArtGrp, true, true);
                        }
                        else
                        {
                            tmpKumUmsCustArtGrp = NDXTmpKumUmsCustArtGrp::find(umsSignature,
                                                                        monthYearSignature,
                                                                        l_Alliance,
                                                                        l_Child,
                                                                        kumUmsCustArtGrp.Companys,
                                                                        ArtGrp, true, true);
                        }
                    }
                    if (tmpKumUmsCustArtGrp == null)
                    {
                        tmpKumUmsCustArtGrp.Party                   = custTablePartyId.Party;
                        tmpKumUmsCustArtGrp.Alliance                = l_Alliance;

                        if (lGetDataOnly)
                        {
                            tmpKumUmsCustArtGrp.Child                   = nDX_TmpCustomerAlliance.CustAccount;
                            tmpKumUmsCustArtGrp.PartyChild            = nDX_TmpCustomerAlliance.CustParty;
                        }
                        else
                        {
                            if (lAllianceValues)
                            {
                                tmpKumUmsCustArtGrp.Child                   = custTablePartyId2.AccountNum;
                                tmpKumUmsCustArtGrp.PartyChild            = custTablePartyId2.Party;
                            }
                            else
                            {
                                tmpKumUmsCustArtGrp.Child                   = l_Child;
                            }
                        }
                        tmpKumUmsCustArtGrp.SalesGroup              = salesGroupId;
                        tmpKumUmsCustArtGrp.Company                 = kumUmsCustArtGrp.Companys;
                        tmpKumUmsCustArtGrp.UmsSignature            = umsSignature;
                        tmpKumUmsCustArtGrp.MonthYearSignature      = monthYearSignature;
                        TmpKumUmsCustArtGrp.ItemGroup                  = ArtGrp;
                        TmpKumUmsCustArtGrp.Name                    = nDX_ArtGrp.BEZ;
                        if (tmpKumUmsCustArtGrp.validateWrite())
                        {
                            tmpKumUmsCustArtGrp.insert();
                        }
                    }
                    if (lThread)
                    {
                        nDXTmpUmsatzClassThreadControl.incActiveCounter();
                    }
                    //}
                    //catch
                    //{
                    //    throw Error(strfmt("@NDX:NDXRecordInTmpKumUmsCustArtGrpNotCreated", accountNum, kumUmsCustArtGrp.ArtGrp()));     // Datensatz in NDXTmpKumUmsCustArtGrp für Account [%1], Artikelgruppe [%2] konnte nicht angelegt werden!
                    //}

                    if (kumUmsCustArtGrp.Jahr   == yearlfdJ)
                    {
                        if (lGetDataOnly)
                        {
                            tmpKumUmsCustArtGrpDeb.setUmsLfdJ(kumUmsCustArtGrp);
                        }
                        tmpKumUmsCustArtGrpAll.addUmsLfdJ(kumUmsCustArtGrp);
                        TmpKumUmsCustArtGrp.addUmsLfdJ(kumUmsCustArtGrp);
                    }
                    else
                    {
                        if (lGetDataOnly)
                        {
                            tmpKumUmsCustArtGrpDeb.setUmsVJ(kumUmsCustArtGrp);
                        }
                        if (lgetDataForAllCompanies)
                        {
                            tmpKumUmsCustArtGrpAll.addUmsVJ(kumUmsCustArtGrp);
                        }
                        TmpKumUmsCustArtGrp.addUmsVJ(kumUmsCustArtGrp);
                    }

                    if (lInfo)
                    {
                        info(strfmt('tmpKumUmsCustArtGrp   : %4.) Alliance [%1] Child [%2] ArtGrp [%3] Firma [%5]'
                        , tmpKumUmsCustArtGrp.Alliance, tmpKumUmsCustArtGrp.Child, tmpKumUmsCustArtGrp.ItemGroup, counter1, tmpKumUmsCustArtGrp.Company ));
                        info(strfmt('tmpKumUmsCustArtGrpAll: %4.) Alliance [%1] Child [%2] ArtGrp [%3] Firma [%5]'
                        , tmpKumUmsCustArtGrpAll.Alliance, tmpKumUmsCustArtGrpAll.Child, tmpKumUmsCustArtGrpAll.ItemGroup, counter1, tmpKumUmsCustArtGrpAll.Company ));

                    }

                    if (lGetDataOnly)
                    {
                        tmpKumUmsCustArtGrpDeb.setDiffValuesPercent(nDX_UmsatzClass, false);
                    }
                    if (lgetDataForAllCompanies)
                    {
                        tmpKumUmsCustArtGrpAll.setDiffValuesPercent(nDX_UmsatzClass, false);
                    }
                    TmpKumUmsCustArtGrp.setDiffValuesPercent(nDX_UmsatzClass, false);
                    if (lGetDataOnly)
                    {
                        tmpKumUmsCustArtGrpDeb.write();
                    }
                    if (lgetDataForAllCompanies && tmpKumUmsCustArtGrpAll.validateWrite())
                    {
                        tmpKumUmsCustArtGrpAll.write();
                    }
                    if ((TmpKumUmsCustArtGrp.RecId != tmpKumUmsCustArtGrpDeb.RecId || tmpKumUmsCustArtGrp.RecVersion == tmpKumUmsCustArtGrpDeb.RecVersion)  && TmpKumUmsCustArtGrp.validateWrite())
                    {
                        TmpKumUmsCustArtGrp.write();
                    }
                    ttscommit;
                }
            }
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= NDXConstants::RetryNum)
            {
                //Error("Deadlock: NDXUmsatzClassThread:2328");
                //throw Exception::Deadlock;
                throw Error(strFmt("@NDXBase:NDXDeadLock", tableId2Name(TmpKumUmsCustArtGrp.TableId)) + " NDXUmsatzClassThread:2328");
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= NDXConstants::RetryNum)
                {
                    //Error("UpdateConflict: NDXUmsatzClassThread:2342");
                    //throw Exception::UpdateConflictNotRecovered;
                    throw Error(strFmt("@NDXBase:NDXUpdateConflict", tableId2Name(TmpKumUmsCustArtGrp.TableId)) + " NDXUmsatzClassThread:2342");
                }
                else
                {
                    retry;
                }
            }
            else
            {
                //Error("UpdateConflict: NDXUmsatzClassThread:2352");
                //throw Exception::UpdateConflict;
                throw Error(strFmt("@NDXBase:NDXUpdateConflict", tableId2Name(TmpKumUmsCustArtGrp.TableId)) + " NDXUmsatzClassThread:2352");
            }
        }

        if (progress)
        {
            progress.kill();
        }

        text = strfmt("@NDX:NDXDetermineItemGroupSalesVolumeParam",
                   NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())),
                    NDXUmsatzConstants::Ende);  //[%1] %2: Artikelgruppenumsatz ermitteln

        if (lThread)
        {           
            NDXTmpUmsatzClassThreadControl::setInfoStatic(nDXTmpUmsatzClassThreadControl, text);
        }

        if (lWithProt)
        {
            NDXUmsatzProt::add(umsSignature, text, NDXProtStart::Stop);
        }

        //ttsbegin;

        // Umsatzanteile berechnen            
        ++counter1;
        nDX_JobManagerJobs.setAction("@NDX:NDXDetermineSalesVolumeShares", l_Alliance, counter1 );            // Umsatzanteile ermitteln
        text = strfmt("@NDX:NDXCalculateSalesVolumeShares",
                    NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())),
                    NDXUmsatzConstants::Start);  //[%1] %2: Umsatzanteile berechnen

        if (lThread)
        {
            NDXTmpUmsatzClassThreadControl::setInfoStatic(nDXTmpUmsatzClassThreadControl, text);
        }

        if (lWithProt)
        {
            NDXUmsatzProt::add(umsSignature, text, NDXProtStart::Start);
        }

        NDXTmpKumUmsCustArtGrp::setUmsAnteil(umsSignature,
                                            monthYearSignature,
                                            l_Alliance,
                                            custTablePartyId.Party,
                                            nDX_UmsatzClass,
                                            lCSIncl);
        //ttscommit;
        // Umsatzanteile berechnen
        text = strfmt("@NDX:NDXCalculateSalesVolumeShares",
                    NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())),
                    NDXUmsatzConstants::Ende);  //[%1] %2: Umsatzanteile berechnen

        if (lThread)
        {
            NDXTmpUmsatzClassThreadControl::setInfoStatic(nDXTmpUmsatzClassThreadControl, text);
            nDXThreadControl.stop();
        }
        if (lWithProt)
        {
            NDXUmsatzProt::add(umsSignature, text, NDXProtStart::Stop);
        }
    }
    nDX_JobManagerJobs.ende();
    return;
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "nDX_UmsatzClass">NDXUmsatzClass</param>
static server void setValues4FormCS(NDXUmsatzClass nDX_UmsatzClass)
{
    NDXTmpKumUmsCust       tmpKumUmsCust;
    NDXKumUmsCustMonat     kumUmsCustMonat;
    NDXUmsatzCompanies      umsatzCompanies;

    AccountNum              accountNum;
    NDXUmsSignature         umsSignature;
    NDXMonthYearSignature   monthYearSignature;
    NDXYear                 yearlfdJ;
    NDXYear                 yearVJ;
    NDXUmsSignature         umsSignatureForm;
    boolean                 lAllianceValues;
    ;

    lAllianceValues = NDXUmsatzClass::AllianceOrSalesGroupValues(nDX_UmsatzClass.parmlAlliance(),
                                                             nDX_UmsatzClass.parmlUseCalculatedData(),
                                                             nDX_UmsatzClass.parmLGetDataOnly());

    accountNum          = lAllianceValues                           ? nDX_UmsatzClass.parmAccountNum()      : nDX_UmsatzClass.parmSalesGroupId();
    //umsSignature        = nDX_UmsatzClass.getCalculatedUser();
    umsSignature        = nDX_UmsatzClass.parmlUseCalculatedData()  ? nDX_UmsatzClass.getCalculatedUser()   : nDX_UmsatzClass.parmUmsSignature();
    yearlfdJ            = nDX_UmsatzClass.parmYearlfdJ();
    yearVJ              = nDX_UmsatzClass.parmYearVJ();
    umsSignatureForm    = nDX_UmsatzClass.parmUmsSignature();
    monthYearSignature  = nDX_UmsatzClass.parmMonthYearSignature();


    // Initialisierung "alle Firmen"
    ttsbegin;
    while select pessimisticlock kumUmsCustMonat
        where kumUmsCustMonat.UmsSignature == umsSignatureForm &&
        kumUmsCustMonat.Company == NDXCompanyBE::AllCompanies
    {
        kumUmsCustMonat.initUmsCS();
        if (kumUmsCustMonat.validateWrite())
        {
            kumUmsCustMonat.update();
        }
    }
    ttscommit;

    // Zentrallager-Umsatzdaten ermitteln
    while select tmpKumUmsCust
        group by Alliance, Company
        where tmpKumUmsCust.Alliance == accountNum &&
        tmpKumUmsCust.UmsSignature == umsSignature &&
        tmpKumUmsCust.MonthYearSignature == monthYearSignature &&
        tmpKumUmsCust.Company != NDXCompanyBE::AllCompanies
    {
        NDXKumUmsCustMonat::UmsCS(
            tmpKumUmsCust.Alliance,
            umsSignature,
            monthYearSignature,
            TmpKumUmsCust.Company,
            yearlfdJ, yearVJ,
            false,
            umsSignatureForm);
    }        
    // Firmen, bei denen kein Umsatz erzeugt wurde initialisieren
    while select umsatzCompanies
        where umsatzCompanies.Active == NoYes::Yes
        notexists join tmpKumUmsCust
        where tmpKumUmsCust.Alliance == accountNum &&
        tmpKumUmsCust.UmsSignature == umsSignature &&
        tmpKumUmsCust.MonthYearSignature == monthYearSignature &&
        tmpKumUmsCust.Company == umsatzCompanies.UK
    {
        NDXKumUmsCustMonat::UmsCS(
            accountNum,
            umsSignature,
            monthYearSignature,
            umsatzCompanies.UK,
            yearlfdJ, yearVJ,
            false,
            umsSignatureForm);
    }        
}
